CREATE TABLE "external_source_events" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "external_source_events_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"source" varchar(64) NOT NULL,
	"source_event_id" varchar(255) NOT NULL,
	"event_type" varchar(32) NOT NULL,
	"amount_cents" bigint NOT NULL,
	"currency" varchar(3) NOT NULL,
	"occurred_at" timestamp (3) with time zone NOT NULL,
	"received_at" timestamp (3) with time zone NOT NULL,
	"external_reference" varchar(255) NOT NULL,
	"internal_payment_id" integer,
	"internal_refund_id" integer,
	"provider_payment_reference" varchar(255),
	"raw_payload" "bytea" NOT NULL,
	"metadata" jsonb NOT NULL,
	"created_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "external_source_events_source_event_id_unique" UNIQUE("source","source_event_id"),
	CONSTRAINT "external_source_events_type_allowed" CHECK ("external_source_events"."event_type" in ('settlement_credit', 'refund_debit')),
	CONSTRAINT "external_source_events_amount_positive" CHECK ("external_source_events"."amount_cents" > 0),
	CONSTRAINT "external_source_events_amount_safe_integer" CHECK ("external_source_events"."amount_cents" <= 9007199254740991),
	CONSTRAINT "external_source_events_currency_eur" CHECK ("external_source_events"."currency" = 'EUR'),
	CONSTRAINT "external_source_events_source_nonblank" CHECK (btrim("external_source_events"."source") <> ''),
	CONSTRAINT "external_source_events_source_event_id_nonblank" CHECK (btrim("external_source_events"."source_event_id") <> ''),
	CONSTRAINT "external_source_events_external_reference_nonblank" CHECK (btrim("external_source_events"."external_reference") <> ''),
	CONSTRAINT "external_source_events_provider_reference_nonblank" CHECK ("external_source_events"."provider_payment_reference" is null or btrim("external_source_events"."provider_payment_reference") <> ''),
	CONSTRAINT "external_source_events_raw_payload_size" CHECK (octet_length("external_source_events"."raw_payload") between 1 and 1048576),
	CONSTRAINT "external_source_events_metadata_object" CHECK (jsonb_typeof("external_source_events"."metadata") = 'object'),
	CONSTRAINT "external_source_events_metadata_size" CHECK (octet_length("external_source_events"."metadata"::text) <= 16384),
	CONSTRAINT "external_source_events_reference_consistency" CHECK ((
      ("external_source_events"."event_type" = 'settlement_credit' and "external_source_events"."internal_refund_id" is null)
      or ("external_source_events"."event_type" = 'refund_debit' and "external_source_events"."internal_payment_id" is null and "external_source_events"."provider_payment_reference" is null)
    ))
);
--> statement-breakpoint
CREATE TABLE "reconciliation_actions" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "reconciliation_actions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"finding_id" integer NOT NULL,
	"action_type" varchar(16) NOT NULL,
	"from_status" varchar(16) NOT NULL,
	"to_status" varchar(16) NOT NULL,
	"actor_type" varchar(16) NOT NULL,
	"actor_id" varchar(128) NOT NULL,
	"reason" varchar(1000) NOT NULL,
	"idempotency_key" varchar(128) NOT NULL,
	"request_fingerprint" varchar(64) NOT NULL,
	"occurred_at" timestamp (3) with time zone NOT NULL,
	"recorded_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "reconciliation_actions_finding_idempotency_unique" UNIQUE("finding_id","idempotency_key"),
	CONSTRAINT "reconciliation_actions_transition_allowed" CHECK ((
      ("reconciliation_actions"."action_type" = 'acknowledge' and "reconciliation_actions"."from_status" = 'open' and "reconciliation_actions"."to_status" = 'acknowledged')
      or ("reconciliation_actions"."action_type" = 'resolve' and "reconciliation_actions"."from_status" in ('open', 'acknowledged') and "reconciliation_actions"."to_status" = 'resolved')
      or ("reconciliation_actions"."action_type" = 'ignore' and "reconciliation_actions"."from_status" in ('open', 'acknowledged') and "reconciliation_actions"."to_status" = 'ignored')
    )),
	CONSTRAINT "reconciliation_actions_actor_operator" CHECK ("reconciliation_actions"."actor_type" = 'operator'),
	CONSTRAINT "reconciliation_actions_actor_id_nonblank" CHECK (btrim("reconciliation_actions"."actor_id") <> ''),
	CONSTRAINT "reconciliation_actions_reason_nonblank" CHECK (btrim("reconciliation_actions"."reason") <> ''),
	CONSTRAINT "reconciliation_actions_idempotency_key_format" CHECK ("reconciliation_actions"."idempotency_key" ~ '^[!-~]{1,128}$'),
	CONSTRAINT "reconciliation_actions_fingerprint_format" CHECK ("reconciliation_actions"."request_fingerprint" ~ '^[0-9a-f]{64}$')
);
--> statement-breakpoint
CREATE TABLE "reconciliation_finding_evidence" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "reconciliation_finding_evidence_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"finding_id" integer NOT NULL,
	"role" varchar(32) NOT NULL,
	"contract_id" integer,
	"installment_id" integer,
	"payment_id" integer,
	"refund_id" integer,
	"ledger_entry_id" integer,
	"stripe_webhook_event_id" integer,
	"external_source_event_id" integer,
	"created_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "reconciliation_evidence_role_allowed" CHECK ("reconciliation_finding_evidence"."role" in ('subject', 'internal_fact', 'internal_effect', 'provider_evidence', 'external_evidence', 'contract_context')),
	CONSTRAINT "reconciliation_evidence_exactly_one_reference" CHECK (num_nonnulls("reconciliation_finding_evidence"."contract_id", "reconciliation_finding_evidence"."installment_id", "reconciliation_finding_evidence"."payment_id", "reconciliation_finding_evidence"."refund_id", "reconciliation_finding_evidence"."ledger_entry_id", "reconciliation_finding_evidence"."stripe_webhook_event_id", "reconciliation_finding_evidence"."external_source_event_id") = 1)
);
