CREATE TABLE "reconciliation_findings" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "reconciliation_findings_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"run_id" integer NOT NULL,
	"rule_code" varchar(64) NOT NULL,
	"rule_version" integer NOT NULL,
	"severity" varchar(16) NOT NULL,
	"subject_type" varchar(32) NOT NULL,
	"subject_id" integer NOT NULL,
	"amount_delta_cents" bigint,
	"currency" varchar(3) NOT NULL,
	"status" varchar(16) NOT NULL,
	"fingerprint" varchar(64) NOT NULL,
	"created_at" timestamp (3) with time zone NOT NULL,
	"status_updated_at" timestamp (3) with time zone NOT NULL,
	CONSTRAINT "reconciliation_findings_run_fingerprint_unique" UNIQUE("run_id","fingerprint"),
	CONSTRAINT "reconciliation_findings_rule_allowed" CHECK ("reconciliation_findings"."rule_code" in ('STRIPE_SUCCESS_MISSING_INTERNAL_PAYMENT', 'INTERNAL_PAYMENT_MISSING_BANK_SETTLEMENT', 'BANK_SETTLEMENT_AMOUNT_MISMATCH', 'INTERNAL_REFUND_MISSING_BANK_OUTFLOW', 'ORPHAN_BANK_MOVEMENT')),
	CONSTRAINT "reconciliation_findings_rule_version_one" CHECK ("reconciliation_findings"."rule_version" = 1),
	CONSTRAINT "reconciliation_findings_severity_allowed" CHECK ("reconciliation_findings"."severity" in ('warning', 'critical')),
	CONSTRAINT "reconciliation_findings_subject_allowed" CHECK ("reconciliation_findings"."subject_type" in ('payment', 'refund', 'stripe_webhook_event', 'external_source_event')),
	CONSTRAINT "reconciliation_findings_rule_semantics" CHECK ((
      ("reconciliation_findings"."rule_code" = 'STRIPE_SUCCESS_MISSING_INTERNAL_PAYMENT' and "reconciliation_findings"."severity" = 'critical' and "reconciliation_findings"."subject_type" = 'stripe_webhook_event')
      or ("reconciliation_findings"."rule_code" = 'INTERNAL_PAYMENT_MISSING_BANK_SETTLEMENT' and "reconciliation_findings"."severity" = 'warning' and "reconciliation_findings"."subject_type" = 'payment')
      or ("reconciliation_findings"."rule_code" = 'BANK_SETTLEMENT_AMOUNT_MISMATCH' and "reconciliation_findings"."severity" = 'critical' and "reconciliation_findings"."subject_type" = 'payment')
      or ("reconciliation_findings"."rule_code" = 'INTERNAL_REFUND_MISSING_BANK_OUTFLOW' and "reconciliation_findings"."severity" = 'warning' and "reconciliation_findings"."subject_type" = 'refund')
      or ("reconciliation_findings"."rule_code" = 'ORPHAN_BANK_MOVEMENT' and "reconciliation_findings"."severity" = 'warning' and "reconciliation_findings"."subject_type" = 'external_source_event')
    )),
	CONSTRAINT "reconciliation_findings_subject_id_positive" CHECK ("reconciliation_findings"."subject_id" > 0),
	CONSTRAINT "reconciliation_findings_delta_safe_integer" CHECK ("reconciliation_findings"."amount_delta_cents" is null or "reconciliation_findings"."amount_delta_cents" between -9007199254740991 and 9007199254740991),
	CONSTRAINT "reconciliation_findings_currency_eur" CHECK ("reconciliation_findings"."currency" = 'EUR'),
	CONSTRAINT "reconciliation_findings_status_allowed" CHECK ("reconciliation_findings"."status" in ('open', 'acknowledged', 'resolved', 'ignored')),
	CONSTRAINT "reconciliation_findings_fingerprint_format" CHECK ("reconciliation_findings"."fingerprint" ~ '^[0-9a-f]{64}$')
);
