CREATE TABLE "reconciliation_runs" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "reconciliation_runs_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"scope_type" varchar(16) NOT NULL,
	"scope_id" integer,
	"cutoff" timestamp (3) with time zone NOT NULL,
