	CONSTRAINT "reconciliation_runs_rule_set_v1" CHECK ("reconciliation_runs"."rule_set_version" = 'reconciliation-v1'),
	CONSTRAINT "reconciliation_runs_status_completed" CHECK ("reconciliation_runs"."status" = 'completed'),
	CONSTRAINT "reconciliation_runs_fingerprint_format" CHECK ("reconciliation_runs"."run_fingerprint" ~ '^[0-9a-f]{64}$')
);
