CREATE FUNCTION reject_reconciliation_immutable_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
	RAISE EXCEPTION '% is immutable', TG_TABLE_NAME;
END;
$$;
--> statement-breakpoint
