CREATE FUNCTION protect_reconciliation_finding_history()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'reconciliation_findings cannot be deleted';
	END IF;

	IF OLD.id IS DISTINCT FROM NEW.id
		OR OLD.run_id IS DISTINCT FROM NEW.run_id
		OR OLD.rule_code IS DISTINCT FROM NEW.rule_code
		OR OLD.rule_version IS DISTINCT FROM NEW.rule_version
		OR OLD.severity IS DISTINCT FROM NEW.severity
		OR OLD.subject_type IS DISTINCT FROM NEW.subject_type
		OR OLD.subject_id IS DISTINCT FROM NEW.subject_id
		OR OLD.amount_delta_cents IS DISTINCT FROM NEW.amount_delta_cents
		OR OLD.currency IS DISTINCT FROM NEW.currency
		OR OLD.fingerprint IS DISTINCT FROM NEW.fingerprint
		OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
		RAISE EXCEPTION 'reconciliation_findings historical fields cannot be changed';
	END IF;

	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER reconciliation_findings_protect_history
BEFORE UPDATE OR DELETE ON "reconciliation_findings"
FOR EACH ROW EXECUTE FUNCTION protect_reconciliation_finding_history();
